package alphametics

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Solve parses an alphametics puzzle of the form "WORD + WORD == RESULT"
// and returns a mapping of each letter to a distinct digit such that the
// equation holds, or an error if no such assignment exists.
func Solve(puzzle string) (map[string]int, error) {
	words, err := parse(puzzle)
	if err != nil {
		return nil, err
	}
	coeffs, leading := analyze(words)
	assignment := make(map[byte]int, len(coeffs))
	if solve(assignment, coeffs, leading) {
		result := make(map[string]int, len(assignment))
		for letter, digit := range assignment {
			result[string(letter)] = digit
		}
		return result, nil
	}
	return nil, errors.New("no solution")
}

// parse splits the puzzle into the addends followed by the result word.
func parse(puzzle string) ([]string, error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid puzzle %q: expected exactly one '=='", puzzle)
	}
	addends := strings.Split(parts[0], "+")
	result := strings.TrimSpace(parts[1])
	if result == "" {
		return nil, fmt.Errorf("invalid puzzle %q: empty result", puzzle)
	}
	words := make([]string, 0, len(addends)+1)
	for _, addend := range addends {
		addend = strings.TrimSpace(addend)
		if addend == "" {
			return nil, fmt.Errorf("invalid puzzle %q: empty addend", puzzle)
		}
		words = append(words, addend)
	}
	words = append(words, result)
	return words, nil
}

// analyze turns the words into a linear constraint: for each letter it
// accumulates the total place-value coefficient such that the equation
// holds exactly when the sum of coefficient(letter) * digit(letter) is 0.
// It also records which letters may not be assigned zero.
func analyze(words []string) (map[byte]int64, map[byte]bool) {
	coeffs := make(map[byte]int64)
	leading := make(map[byte]bool)
	for i, word := range words {
		sign := int64(1)
		if i == len(words)-1 {
			sign = -1
		}
		if len(word) > 1 {
			leading[word[0]] = true
		}
		for pos, c := range word {
			coeffs[byte(c)] += sign * pow10[len(word)-1-pos]
		}
	}
	return coeffs, leading
}

// solve backtracks over letter assignments, pruning branches whose partial
// sum cannot possibly reach zero.
func solve(assignment map[byte]int, coeffs map[byte]int64, leading map[byte]bool) bool {
	letters := make([]byte, 0, len(coeffs))
	for letter := range coeffs {
		letters = append(letters, letter)
	}
	sort.Slice(letters, func(i, j int) bool {
		ai, aj := abs64(coeffs[letters[i]]), abs64(coeffs[letters[j]])
		if ai != aj {
			return ai > aj
		}
		return letters[i] < letters[j]
	})

	used := make([]bool, 10)
	return backtrack(letters, coeffs, leading, assignment, used, 0, 0)
}

func backtrack(letters []byte, coeffs map[byte]int64, leading map[byte]bool, assignment map[byte]int, used []bool, idx int, sum int64) bool {
	if idx == len(letters) {
		return sum == 0
	}
	// Prune if even the most favorable assignment of the remaining
	// letters cannot bring the total back to zero.
	minRem, maxRem := sum, sum
	for _, remaining := range letters[idx:] {
		c := coeffs[remaining]
		if c > 0 {
			maxRem += c * 9
		} else {
			minRem += c * 9
		}
	}
	if minRem > 0 || maxRem < 0 {
		return false
	}
	letter := letters[idx]
	for digit := 0; digit <= 9; digit++ {
		if used[digit] || (digit == 0 && leading[letter]) {
			continue
		}
		used[digit] = true
		assignment[letter] = digit
		if backtrack(letters, coeffs, leading, assignment, used, idx+1, sum+coeffs[letter]*int64(digit)) {
			return true
		}
		used[digit] = false
	}
	return false
}

var pow10 = func() []int64 {
	table := make([]int64, 19)
	table[0] = 1
	for i := 1; i < len(table); i++ {
		table[i] = table[i-1] * 10
	}
	return table
}()

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

